import { test, expect } from '@playwright/test';
import type { Page, Browser } from '@playwright/test';
import {
  authFile, rowOf, openList, search, openNewCustomer, rest, cardTag,
  BTN_SAVE, SWITCH_LINK, ST_NO_CATALOG, ST_PENDING, ST_INVITED, ST_ACTIVE, TEST_PHONE,
} from './_customers';

test.use({ storageState: authFile('admin') });

const ST_DISABLED = 'מושבת';
const STATUSES = [ST_ACTIVE, ST_INVITED, ST_PENDING, ST_NO_CATALOG, ST_DISABLED];
const TEST_CARD = '/customers/a30f4767-3f86-4a49-a441-ecfd2faad6d0'; // «test», тел. 0531231235, «פעיל», с заказами
const ALINA = 'אלינה בדיקה';
const ALINA_PHONE = '0528559186'; // «ממתין להזמנה» (ссылка создана)
const INVITES = /\/rest\/v1\/customer_invites\?/;
const ORDERS = /\/rest\/v1\/orders\?/;
const KPI = ['הזמנה אחרונה', 'יתרה פתוחה', 'סה"כ רכישות', "מס' הזמנות"];
const EMPTY_RE = 'לא נמצאו|אין תוצאות';
const INVITE_BTN = 'הזמנה לקטלוג';

type Row = { phone: string; text: string; status: string };
type Frame = { t: number; rows: Row[]; tag: string | null; kpi: Record<string, string> | null; btnInvite: boolean; menuJoin: boolean; empty: string; skel: number };

// ── наблюдатель кадров (в странице) ─────────────────────────────────────────────────────────
function observer({ labels, empty }: { labels: string[]; empty: string }) {
  const w = window as unknown as { __qaObs?: boolean; __qaLog: unknown[]; __qaSnap: () => unknown };
  if (w.__qaObs) return;
  w.__qaObs = true;
  w.__qaLog = [];
  const pulse = (el: Element | null | undefined) => !!el && (el.matches('[class*=animate-pulse]') || !!el.querySelector('[class*=animate-pulse]'));
  const txt = (el: Element) => (el as HTMLElement).innerText.trim();
  const snap = () => {
    const main = document.querySelector('main');
    if (!main) return null;
    // строка клиента — role=button с кнопкой «פעולות»; статус — ячейка перед ячейкой с этой кнопкой
    const rows = [...main.querySelectorAll('[role=button]')].filter((r) => r.querySelector('button')).map((r) => {
      const cells = [...r.children];
      const a = cells.map((c) => !!(c.matches('button') || c.querySelector('button'))).lastIndexOf(true);
      const cell = a > 0 ? cells[a - 1] : cells[cells.length - 1];
      const text = txt(r).replace(/\s+/g, ' ');
      return { phone: (text.match(/0\d{8,11}/) || [''])[0], text, status: (cell && txt(cell)) || (pulse(cell) ? 'SKEL' : 'EMPTY') };
    });
    const h1 = main.querySelector('h1');
    let tag: string | null = null;
    let kpi: Record<string, string> | null = null;
    if (h1 && h1.parentElement && /^\/customers\/[^/]+$/.test(location.pathname)) {
      tag = [...h1.parentElement.children].filter((x) => x !== h1).map((x) => txt(x) || (pulse(x) ? 'SKEL' : 'EMPTY')).join(',') || 'NOTAG';
      kpi = {};
      for (const l of labels) {
        const leaf = [...main.querySelectorAll('*')].find((x) => !x.children.length && (x.textContent || '').trim() === l);
        const box = leaf?.parentElement;
        if (!box) { kpi[l] = 'NONE'; continue; }
        kpi[l] = txt(box).replace(l, '').trim().split('\n')[0] || (pulse(box) ? 'SKEL' : 'EMPTY');
      }
    }
    return {
      rows, tag, kpi,
      btnInvite: [...document.querySelectorAll('button,a')].some((b) => (b as HTMLElement).innerText.includes('הזמנה לקטלוג')),
      menuJoin: [...document.querySelectorAll('[role=menuitem]')].some((m) => (m as HTMLElement).innerText.includes('קישור הצטרפות')),
      empty: ((main as HTMLElement).innerText.match(new RegExp(empty)) || [''])[0],
      skel: main.querySelectorAll('[class*=animate-pulse]').length,
    };
  };
  let last = '';
  const rec = () => {
    try {
      const s = snap();
      if (!s) return;
      const k = JSON.stringify(s);
      if (k !== last) { last = k; w.__qaLog.push({ t: Math.round(performance.now()), ...s }); }
    } catch { /* кадр без main */ }
  };
  w.__qaSnap = snap;
  const start = () => { new MutationObserver(rec).observe(document, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['class'] }); rec(); };
  if (document.documentElement) start(); else document.addEventListener('readystatechange', start, { once: true });
}

const installObserver = (page: Page) => page.addInitScript(observer, { labels: KPI, empty: EMPTY_RE });
const frames = (page: Page) => page.evaluate(() => (window as unknown as { __qaLog: Frame[] }).__qaLog);
const current = (page: Page) => page.evaluate(() => (window as unknown as { __qaSnap: () => Frame }).__qaSnap());
const rowIn = (f: Frame, key: string) => f.rows.find((r) => r.phone === key || (!/^0\d+$/.test(key) && r.text.includes(key)));
const isStatus = (s: string | null | undefined) => !!s && STATUSES.some((x) => s.split(',').includes(x));

/**
 * Держит GET-запросы по url до явного release(). first — первый запрос перехвачен (задержка реально действует).
 * release() возвращает число кадров, записанных ДО отпускания (они гарантированно до ответа), и ждёт ответ.
 */
async function hold(page: Page, url: RegExp) {
  let open!: () => void;
  const gate = new Promise<void>((r) => (open = r));
  let gotFirst!: () => void;
  const first = new Promise<void>((r) => (gotFirst = r));
  let released = false;
  await page.route(url, async (route) => {
    if (route.request().method() === 'GET' && !released) { gotFirst(); await gate; }
    await route.fallback().catch(() => { /* страница закрыта */ });
  });
  return {
    first,
    async release() {
      const mark = (await frames(page)).length;
      const resp = page.waitForResponse((r) => url.test(r.url()) && r.request().method() === 'GET', { timeout: 30_000 });
      released = true;
      open();
      await resp;
      return mark;
    },
  };
}

/** Кадры, где статус строки уже показан, но расходится с итоговым (итог — последний статус после ответа). */
function wrongStatusFrames(log: Frame[], mark: number) {
  const final = new Map<string, string>();
  for (const f of log.slice(mark)) for (const r of f.rows) if (r.phone && isStatus(r.status)) final.set(r.phone, r.status);
  return log.flatMap((f) => f.rows.filter((r) => r.phone && isStatus(r.status) && final.has(r.phone) && final.get(r.phone) !== r.status)
    .map((r) => `${f.t}ms ${r.phone}: «${r.status}», итог «${final.get(r.phone)}»`));
}

const noCatalogFrames = (log: Frame[], phone: string) =>
  log.filter((f) => rowIn(f, phone)?.status === ST_NO_CATALOG).map((f) => `${f.t}ms`);

const tile = (page: Page, label: string) =>
  page.getByRole('main').getByText(label, { exact: true }).locator('xpath=following-sibling::*[1]');

async function waitListShell(page: Page) {
  await expect(page.getByRole('heading', { level: 1, name: 'לקוחות' })).toBeVisible({ timeout: 30_000 });
}

async function openTestCard(page: Page) {
  await page.goto(TEST_CARD);
  await expect(page.getByRole('heading', { level: 1, name: 'test', exact: true })).toBeVisible({ timeout: 30_000 });
}

