const NAME = `QA-AUTO-cust-08cb68-${Date.now().toString().slice(-7)}`;

async function adminPage(browser: Browser, baseURL: string | undefined) {
  const ctx = await browser.newContext({ storageState: authFile('admin'), baseURL, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  return { ctx, page: await ctx.newPage() };
}

test.describe('customers — QA-AUTO בלי קישור ומושבת בזמן טעינה (#08cb68)', () => {
  test.describe.configure({ mode: 'serial' });
  let id = '';

  test.beforeAll(async ({ browser }, testInfo) => {
    const { ctx, page } = await adminPage(browser, testInfo.project.use.baseURL);
    try {
      await openList(page);
      const dlg = await openNewCustomer(page);
      const sw = dlg.getByRole('switch', { name: SWITCH_LINK });
      await sw.click();
      await expect(sw).toHaveAttribute('aria-checked', 'false');
      await dlg.getByRole('textbox', { name: /^שם העסק/ }).fill(NAME);
      const [resp] = await Promise.all([
        page.waitForResponse((r) => /\/rest\/v1\/customers(\?|$)/.test(r.url()) && r.request().method() === 'POST'),
        dlg.getByRole('button', { name: BTN_SAVE }).click(),
      ]);
      expect(resp.status(), `POST customers «${NAME}»`).toBe(201);
      await expect(page.getByRole('dialog')).toHaveCount(0, { timeout: 15_000 });
      const body = await resp.json();
      id = (Array.isArray(body) ? body[0] : body).id;
    } finally {
      await ctx.close();
    }
  });

  test.afterAll(async ({ browser }, testInfo) => {
    const { ctx, page } = await adminPage(browser, testInfo.project.use.baseURL);
    try {
      await openList(page);
      const found = await rest(page, 'GET', `customers?select=id&name=eq.${encodeURIComponent(NAME)}`);
      if (Array.isArray(found.json) && found.json.length) {
        await search(page, NAME);
        const row = rowOf(page, NAME);
        await expect(row).toBeVisible({ timeout: 20_000 });
        await row.getByRole('button', { name: 'פעולות' }).click();
        await page.getByRole('menuitem', { name: /^מחיקה/ }).click();
        const dlg = page.getByRole('dialog');
        await expect(dlg.getByRole('heading', { name: 'מחיקת לקוח' })).toBeVisible();
        const [del] = await Promise.all([
          page.waitForResponse((r) => /\/rest\/v1\/rpc\/delete_customer/.test(r.url()) && r.request().method() === 'POST'),
          dlg.getByRole('button', { name: /^מחיקה/ }).click(),
        ]);
        expect(del.ok(), `rpc delete_customer → ${del.status()}`).toBe(true);
        await expect(row).toHaveCount(0, { timeout: 20_000 });
      }
      const left = await rest(page, 'GET', `customers?select=id&name=eq.${encodeURIComponent(NAME)}`);
      expect(left.json, `клиент ${NAME} удалён`).toEqual([]);
    } finally {
      await ctx.close();
    }
  });

  test('לקוח בלי קישור: ברשימה ובכרטיס — שלד עד תשובת customer_invites, אחר כך «ללא כניסה לקטלוג» #08cb68 #5a2dbd @desktop @data', async ({ page }) => {
    test.skip(!id, 'клиент QA-AUTO не создан');
    await installObserver(page);

    let inv = await hold(page, INVITES);
    await page.goto('/customers');
    await inv.first;
    await waitListShell(page);
    await search(page, NAME);
    const row = rowOf(page, NAME);
    await expect(row).toBeVisible({ timeout: 30_000 });
    await expect.poll(async () => rowIn(await current(page), NAME)?.status, { message: 'статус до ответа — скелет' }).toBe('SKEL');
    let mark = await inv.release();
    await expect(row).toContainText(ST_NO_CATALOG, { timeout: 20_000 });
    await expect(row).not.toContainText(ST_PENDING);
    let log = await frames(page);
    expect(log.slice(0, mark).filter((f) => isStatus(rowIn(f, NAME)?.status)).map((f) => `${f.t}ms ${rowIn(f, NAME)!.status}`), 'до ответа без статуса').toEqual([]);

    inv = await hold(page, INVITES);
    await page.goto(`/customers/${id}`);
    await inv.first;
    await expect(page.getByRole('heading', { level: 1, name: NAME })).toBeVisible({ timeout: 30_000 });
    await expect.poll(async () => (await current(page)).tag, { message: 'тег до ответа — скелет' }).toBe('SKEL');
    mark = await inv.release();
    await expect(cardTag(page, ST_NO_CATALOG)).toBeVisible({ timeout: 20_000 });
    log = await frames(page);
    expect(log.slice(0, mark).filter((f) => isStatus(f.tag)).map((f) => `${f.t}ms ${f.tag}`), 'тег до ответа без статуса').toEqual([]);
  });

  test('לקוח מושבת: «מושבת» מוצג מיד — ברשימה ובכרטיס עוד לפני תשובת customer_invites, בלי שלד #08cb68 @desktop @data', async ({ page }) => {
    test.skip(!id, 'клиент QA-AUTO не создан');
    await openList(page);
    await search(page, NAME);
    const row = rowOf(page, NAME);
    await expect(row).toBeVisible({ timeout: 30_000 });
    await row.getByRole('button', { name: 'פעולות' }).click();
    await page.getByRole('menuitem', { name: 'השבתת לקוח' }).click();
    await expect(row).toContainText(ST_DISABLED, { timeout: 15_000 });

    await installObserver(page);
    let inv = await hold(page, INVITES);
    await page.goto('/customers');
    await inv.first;
    await waitListShell(page);
    await search(page, NAME);
    await expect(row).toContainText(ST_DISABLED, { timeout: 30_000 }); // customer_invites ещё задержан
    let mark = await inv.release();
    let log = await frames(page);
    const listFrames = log.slice(0, mark).filter((f) => rowIn(f, NAME));
    expect(listFrames.length, 'строка показана до ответа').toBeGreaterThan(0);
    const wrongOrSkel = (v: string | null | undefined) => !!v && v !== ST_DISABLED && (v === 'SKEL' || isStatus(v));
    expect(listFrames.filter((f) => wrongOrSkel(rowIn(f, NAME)!.status)).map((f) => `${f.t}ms ${rowIn(f, NAME)!.status}`),
      'до ответа строка сразу «מושבת» (без скелета)').toEqual([]);

    inv = await hold(page, INVITES);
    await page.goto(`/customers/${id}`);
    await inv.first;
    await expect(page.getByRole('heading', { level: 1, name: NAME })).toBeVisible({ timeout: 30_000 });
    await expect(cardTag(page, ST_DISABLED)).toBeVisible(); // customer_invites ещё задержан
    mark = await inv.release();
    log = await frames(page);
    expect(log.slice(0, mark).filter((f) => wrongOrSkel(f.tag)).map((f) => `${f.t}ms ${f.tag}`),
      'тег карточки сразу «מושבת» (без скелета)').toEqual([]);
  });
});
